import React, { createContext, useState, useEffect } from "react";
import axios from "axios";

export const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  // Check if user is still logged in by verifying with backend
  useEffect(() => {
    const checkAuth = async () => {
      try {
        // Try to fetch user data - if valid cookie exists, this will work
        const res = await axios.get("http://localhost:5000/api/events/users", { withCredentials: true });
        // If successful, user has a valid token cookie
        if (res.data && res.data.length >= 0) {
          // Try to get user from sessionStorage (set during login)
          const userData = JSON.parse(sessionStorage.getItem("user"));
          if (userData) {
            setUser(userData);
          }
        }
      } catch (err) {
        // No valid token, user is not authenticated
        sessionStorage.removeItem("user");
        setUser(null);
      } finally {
        setIsLoading(false);
      }
    };
    
    checkAuth();
  }, []);

  const login = async (email, password) => {
    const res = await axios.post("http://localhost:5000/api/auth/login", { email, password }, { withCredentials: true });
    const { user } = res.data;

    // Store user info in sessionStorage (NOT the token - that's in HTTP-only cookie)
    sessionStorage.setItem("user", JSON.stringify(user));
    setUser(user);
  };

  const logout = () => {
    sessionStorage.removeItem("user");
    setUser(null);
    // Cookie will be cleared by backend on logout
    axios.post("http://localhost:5000/api/auth/logout", {}, { withCredentials: true }).catch(() => {});
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, isLoading }}>
      {children}
    </AuthContext.Provider>
  );
};
